// Regenerates the generated portions of src/content/docs/tools.md from
// src/data/tools.json (itself generated by package/scripts/dump-tool-catalog.sh from the
// real LxTool instances) — so the tool reference can never drift from the actual schemas.
//
// Hand-written prose in tools.md is untouched; only the content between
// `<!-- generated:start:<category> -->` / `<!-- generated:end -->` markers is replaced.
// Every tool in tools.json must appear in exactly one category below — a new tool that
// isn't mapped (or a typo'd name) fails this script loudly instead of silently vanishing
// from the docs.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));

// category key -> tool names, in the order they should render within the category.
const CATEGORIES = {
  discover: [
    'get_status',
    'get_project_info',
    'get_tempo',
    'list_channels',
    'get_channel',
    'list_parameters',
    'list_available_patterns',
    'list_available_effects',
    'list_available_modulators',
    'list_modulations',
    'get_parameter',
    'get_palette',
    'list_snapshots',
    'get_frame',
    'get_component_doc',
  ],
  parameters: ['set_parameter'],
  structure: [
    'add_channel',
    'remove_channel',
    'add_pattern',
    'remove_pattern',
    'move_pattern',
    'activate_pattern',
    'add_effect',
    'remove_effect',
    'move_effect',
  ],
  modulation: [
    'add_modulator',
    'remove_modulator',
    'wire_modulator',
    'wire_trigger',
    'remove_modulation',
    'fire_trigger',
  ],
  palette: [
    'save_swatch',
    'set_swatch',
    'remove_swatch',
    'move_swatch',
    'add_color',
    'remove_color',
    'add_snapshot',
    'recall_snapshot',
    'update_snapshot',
    'remove_snapshot',
  ],
  views: ['get_views', 'add_view', 'remove_view'],
  fixtures: [
    'describe_model',
    'get_fixture_format',
    'list_available_fixtures',
    'list_fixtures',
    'get_fixture',
    'get_output_map',
    'add_fixture',
    'remove_fixture',
    'move_fixture',
    'duplicate_fixture',
    'set_fixture_params',
    'set_fixture_tags',
    'reload_fixtures',
  ],
  midi: ['list_midi_devices', 'list_midi_mappings', 'list_midi_surfaces',
    'add_midi_mapping', 'remove_midi_mapping', 'set_midi_input', 'set_midi_surface_enabled'],
};

function schemaTypeLabel(schema) {
  if (!schema) return '—';
  const base = Array.isArray(schema.type) ? schema.type.join(' \\| ') : (schema.type ?? 'any');
  if (schema.type === 'array' && schema.items?.type) {
    return `array<${schema.items.type}>`;
  }
  return base;
}

function schemaConstraints(schema) {
  if (!schema) return '—';
  const bits = [];
  if (schema.enum) bits.push('one of: ' + schema.enum.map((v) => `\`${v}\``).join(', '));
  if (schema.minimum !== undefined || schema.maximum !== undefined) {
    bits.push(`${schema.minimum ?? '-∞'}–${schema.maximum ?? '∞'}`);
  }
  return bits.length ? bits.join('; ') : '—';
}

function escapeCell(text) {
  return String(text ?? '').replaceAll('|', '\\|').replaceAll('\n', ' ');
}

function renderTool(tool) {
  const badge = tool.readOnly ? '_read-only_' : '_mutating_';
  const props = tool.inputSchema?.properties ?? {};
  const required = new Set(tool.inputSchema?.required ?? []);
  const paramNames = Object.keys(props);

  const lines = [];
  lines.push(`### \`${tool.name}\``);
  lines.push('');
  lines.push(badge);
  lines.push('');
  lines.push(escapeCell(tool.description));
  lines.push('');

  if (paramNames.length === 0) {
    lines.push('No parameters.');
  } else {
    lines.push('| param | type | required | constraints | description |');
    lines.push('|---|---|---|---|---|');
    for (const name of paramNames) {
      const schema = props[name];
      lines.push(
        `| \`${name}\` | ${schemaTypeLabel(schema)} | ${required.has(name) ? 'yes' : 'no'} | ` +
          `${schemaConstraints(schema)} | ${escapeCell(schema.description)} |`,
      );
    }
  }
  lines.push('');
  return lines.join('\n');
}

function renderCategory(toolsByName, names) {
  return names.map((name) => renderTool(toolsByName[name])).join('\n').trimEnd() + '\n';
}

const catalog = JSON.parse(await readFile(here('../src/data/tools.json'), 'utf8'));
const toolsByName = Object.fromEntries(catalog.map((t) => [t.name, t]));

// Drift guard: every catalog tool must be mapped to exactly one category.
const mappedNames = Object.values(CATEGORIES).flat();
const mappedCounts = new Map();
for (const name of mappedNames) {
  mappedCounts.set(name, (mappedCounts.get(name) ?? 0) + 1);
}
const catalogNames = new Set(catalog.map((t) => t.name));
const unmapped = catalog.map((t) => t.name).filter((name) => !mappedCounts.has(name));
const duplicateMapped = [...mappedCounts.entries()].filter(([, count]) => count > 1).map(([name]) => name);
const unknownMapped = mappedNames.filter((name) => !catalogNames.has(name));

if (unmapped.length || duplicateMapped.length || unknownMapped.length) {
  const problems = [];
  if (unmapped.length) problems.push(`unmapped tools (add to a category in generate-tool-reference.mjs): ${unmapped.join(', ')}`);
  if (duplicateMapped.length) problems.push(`tools mapped to more than one category: ${duplicateMapped.join(', ')}`);
  if (unknownMapped.length) problems.push(`mapped names that no longer exist in tools.json: ${unknownMapped.join(', ')}`);
  console.error('generate-tool-reference.mjs: category mapping is out of sync with tools.json:\n  ' + problems.join('\n  '));
  process.exit(1);
}

const docPath = here('../src/content/docs/tools.md');
let doc = await readFile(docPath, 'utf8');

for (const [category, names] of Object.entries(CATEGORIES)) {
  const startMarker = `<!-- generated:start:${category} -->`;
  const endMarker = '<!-- generated:end -->';
  const startIdx = doc.indexOf(startMarker);
  if (startIdx === -1) {
    console.error(`generate-tool-reference.mjs: missing marker ${startMarker} in tools.md`);
    process.exit(1);
  }
  const contentStart = startIdx + startMarker.length;
  const endIdx = doc.indexOf(endMarker, contentStart);
  if (endIdx === -1) {
    console.error(`generate-tool-reference.mjs: missing ${endMarker} after ${startMarker} in tools.md`);
    process.exit(1);
  }
  const generated = renderCategory(toolsByName, names);
  doc = doc.slice(0, contentStart) + '\n\n' + generated + '\n' + doc.slice(endIdx);
}

await writeFile(docPath, doc);
console.log(`wrote ${catalog.length} tools across ${Object.keys(CATEGORIES).length} categories into src/content/docs/tools.md`);
